INSERT INTO _migration_626_expected (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_bece_intsci_s3_045', 'topic_bece_science_methods', 'subj_bece_science', 'exam_bece', NULL, NULL, 'A school is setting up a small science corner with basic instruments and safety rules.', 'structured', NULL, NULL, '(a) Any two of: wear eye protection and tie back long hair; never taste chemicals; wash hands after practical work; report any breakage, spill or injury to the teacher at once; handle hot equipment with care (1 each). (b) A (beam or electronic) balance (1). (c) Any two of: tractors and other machines prepare land faster than hand tools; mobile phones give weather forecasts and market prices; irrigation pumps water crops in the dry season; improved storage and processing equipment reduce post-harvest losses (1 each).', '(a) Any two of: wear eye protection and tie back long hair; never taste chemicals; wash hands after practical work; report any breakage, spill or injury to the teacher at once; handle hot equipment with care (1 each). (b) A (beam or electronic) balance (1). (c) Any two of: tractors and other machines prepare land faster than hand tools; mobile phones give weather forecasts and market prices; irrigation pumps water crops in the dry season; improved storage and processing equipment reduce post-harvest losses (1 each).', 'medium', '5', '5', NULL, NULL, NULL, '1', NULL, NULL, 'State', 'AO2', NULL, NULL, 'board_waec'),
('q_bece_intsci_s3_046', 'topic_bece_science_earth_space', 'subj_bece_science', 'exam_bece', NULL, NULL, 'The Moon shines brightly at night, yet it produces no light of its own. Why can we see the Moon, and why does its shape appear to change through the month?', 'multiple_choice', NULL, '["A. The Earth’s shadow covers the Moon a little more every night","B. The Moon burns its fuel slowly, so it dims each month","C. We see sunlight reflected from the Moon, and the changing amount of its lit half that faces us causes the phases","D. Clouds covering the Moon make it appear to change shape"]', 'C', 'The Moon is visible because it reflects sunlight. As it orbits the Earth we see different amounts of its sunlit half, producing the phases from new moon to full moon and back. (The Earth’s shadow causes a lunar eclipse, which is rare — not the monthly phases; the Moon has no fuel to burn, and clouds can hide the Moon but do not cause its phases.) Therefore the correct answer is C: We see sunlight reflected from the Moon, and the changing amount of its lit half that faces us causes the phases.', 'hard', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Explain', 'AO3', NULL, NULL, 'board_waec'),
('q_bece_intsci_s3_047', 'topic_bece_science_earth_space', 'subj_bece_science', 'exam_bece', NULL, NULL, 'Places near the equator are generally hotter than places near the poles. Which statement best explains this?', 'multiple_choice', NULL, '["A. The equator is much closer to the Sun than the poles","B. The poles reflect all sunlight back into space","C. The Earth stops rotating at the poles, so they receive no heat","D. At the equator the Sun’s rays strike the ground almost directly, concentrating their energy on a smaller area"]', 'D', 'At the equator the Sun’s rays hit the surface nearly at right angles, so their energy is concentrated over a small area and heating is strong. Near the poles the same rays arrive at a slant and spread over a larger area, giving less heating per unit area. (The difference in distance to the Sun is negligible compared with the Earth-Sun distance, and the Earth rotates on its axis everywhere.) Therefore the correct answer is D: At the equator the Sun’s rays strike the ground almost directly, concentrating their energy on a smaller area.', 'hard', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Explain', 'AO3', NULL, NULL, 'board_waec'),
('q_bece_intsci_s3_048', 'topic_bece_science_earth_space', 'subj_bece_science', 'exam_bece', NULL, NULL, 'State two differences between igneous rocks and sedimentary rocks.', 'short_answer', NULL, NULL, 'Igneous rocks form when molten magma or lava cools and solidifies; sedimentary rocks form from layers of deposited sediment that are compacted and cemented. Sedimentary rocks often show layers and may contain fossils; igneous rocks do not.', 'Igneous rocks, such as granite and basalt, form when hot molten rock (magma or lava) cools and hardens. Sedimentary rocks, such as sandstone and limestone, form when layers of sediment are pressed and cemented together over a long time, so they usually show visible layers and may contain fossils; igneous rocks have neither layers nor fossils. Any two of these differences earn the marks.', 'medium', '2', '2', '90', NULL, NULL, '1', NULL, NULL, 'State', 'AO1', NULL, NULL, 'board_waec'),
('q_bece_intsci_s3_049', 'topic_bece_science_earth_space', 'subj_bece_science', 'exam_bece', NULL, NULL, 'A rain gauge at a school weather station recorded 12 mm, 18 mm and 15 mm of rain on three days. Calculate the total rainfall and the average daily rainfall.', 'calculation', NULL, NULL, 'Total 45 mm; average 15 mm per day', 'Total rainfall = 12 + 18 + 15 = 45 mm. Average daily rainfall = 45 mm ÷ 3 days = 15 mm per day. Answer: total 45 mm and average 15 mm per day.', 'easy', '4', '2', '120', NULL, NULL, '1', NULL, NULL, 'Calculate', 'AO2', NULL, NULL, 'board_waec'),
('q_bece_intsci_s3_050', 'topic_bece_science_earth_space', 'subj_bece_science', 'exam_bece', NULL, NULL, 'A class is studying how water moves between the Earth and the atmosphere.', 'structured', NULL, NULL, '(a) Evaporation is the process by which the Sun’s heat turns liquid water from rivers, lakes and the sea into water vapour (1). (b) Condensation, in which the water vapour cools and forms tiny droplets in clouds (1); precipitation, in which the water falls back to the Earth as rain (or other forms) (1). (c) It supplies fresh water for drinking, farming and fishing by refilling rivers, streams and wells (1); it supports the rainfall patterns on which food crops and livestock depend (1).', '(a) Evaporation is the process by which the Sun’s heat turns liquid water from rivers, lakes and the sea into water vapour (1). (b) Condensation, in which the water vapour cools and forms tiny droplets in clouds (1); precipitation, in which the water falls back to the Earth as rain (or other forms) (1). (c) It supplies fresh water for drinking, farming and fishing by refilling rivers, streams and wells (1); it supports the rainfall patterns on which food crops and livestock depend (1).', 'medium', '5', '5', NULL, NULL, NULL, '1', NULL, NULL, 'Explain', 'AO2', NULL, NULL, 'board_waec');
INSERT INTO _migration_626_expected_parts (id, question_id, part_label, part_text, marks, correct_answer, display_order) VALUES ('sqp_q_bece_intsci_s3_045_a', 'q_bece_intsci_s3_045', 'a', 'State two safety rules learners must follow when doing experiments.', '2', 'Any two of: wear eye protection and tie back long hair; never taste chemicals; wash hands after practical work; report any breakage, spill or injury to the teacher at once; handle hot equipment with care (1 each).', '1'),
('sqp_q_bece_intsci_s3_045_b', 'q_bece_intsci_s3_045', 'b', 'Name the instrument used to measure the mass of a stone.', '1', 'A (beam or electronic) balance (1).', '2'),
('sqp_q_bece_intsci_s3_045_c', 'q_bece_intsci_s3_045', 'c', 'State two ways in which technology helps farmers in Ghana.', '2', 'Any two of: tractors and other machines prepare land faster than hand tools; mobile phones give weather forecasts and market prices; irrigation pumps water crops in the dry season; improved storage and processing equipment reduce post-harvest losses (1 each).', '3'),
('sqp_q_bece_intsci_s3_050_a', 'q_bece_intsci_s3_050', 'a', 'Define evaporation as it occurs in the water cycle.', '1', 'Evaporation is the process by which the Sun’s heat turns liquid water from rivers, lakes and the sea into water vapour (1).', '1'),
('sqp_q_bece_intsci_s3_050_b', 'q_bece_intsci_s3_050', 'b', 'State the two processes by which water vapour in the atmosphere returns to the Earth.', '2', 'Condensation, in which the water vapour cools and forms tiny droplets in clouds (1); precipitation, in which the water falls back to the Earth as rain (or other forms) (1).', '2'),
('sqp_q_bece_intsci_s3_050_c', 'q_bece_intsci_s3_050', 'c', 'Explain two reasons why the water cycle is important to people in Ghana.', '2', 'It supplies fresh water for drinking, farming and fishing by refilling rivers, streams and wells (1); it supports the rainfall patterns on which food crops and livestock depend (1).', '3');
INSERT INTO _migration_626_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM _migration_626_expected e JOIN questions q ON q.id = e.id WHERE NOT (q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.paper_type_id IS e.paper_type_id AND q.past_paper_id IS e.past_paper_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.round_type IS e.round_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.question_number IS e.question_number AND q.section IS e.section AND q.is_compulsory IS e.is_compulsory AND q.image_url IS e.image_url AND q.syllabus_topic_id IS e.syllabus_topic_id AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective AND q.source_paper_code IS e.source_paper_code AND q.source_question_number IS e.source_question_number AND q.exam_board_id IS e.exam_board_id)) AND NOT EXISTS (SELECT 1 FROM _migration_626_expected e JOIN question_content_releases r ON r.question_id = e.id WHERE NOT (r.batch_id IS 'bece-int-science-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned BECE Integrated Science practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/common-core-programme-ccp/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) AND NOT EXISTS (SELECT 1 FROM _migration_626_expected_parts p JOIN structured_question_parts sp ON sp.id = p.id WHERE NOT (sp.id IS p.id AND sp.question_id IS p.question_id AND sp.part_label IS p.part_label AND sp.part_text IS p.part_text AND sp.marks IS p.marks AND sp.correct_answer IS p.correct_answer AND sp.display_order IS p.display_order)) THEN 1 ELSE 0 END;
INSERT INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) SELECT id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id FROM _migration_626_expected e WHERE NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = e.id);
INSERT INTO structured_question_parts (id, question_id, part_label, part_text, marks, correct_answer, explanation, answer_type, display_order) SELECT p.id, p.question_id, p.part_label, p.part_text, p.marks, p.correct_answer, NULL, 'text', p.display_order FROM _migration_626_expected_parts p WHERE NOT EXISTS (SELECT 1 FROM structured_question_parts sp WHERE sp.id = p.id);
INSERT INTO question_content_releases (question_id, batch_id, quality_assurance, release_channel, content_label, source_url, official_exam_board_content, feedback_enabled) SELECT e.id, 'bece-int-science-sprint3-001', 'automated_beta', 'beta', 'Original BrillaPrep curriculum-aligned BECE Integrated Science practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.', 'https://nacca.gov.gh/common-core-programme-ccp/', 0, 1 FROM _migration_626_expected e WHERE NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = e.id);
INSERT INTO _migration_626_guard(valid) SELECT CASE WHEN (SELECT COUNT(*) FROM questions q JOIN _migration_626_expected e ON e.id = q.id AND q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.paper_type_id IS e.paper_type_id AND q.past_paper_id IS e.past_paper_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.round_type IS e.round_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.question_number IS e.question_number AND q.section IS e.section AND q.is_compulsory IS e.is_compulsory AND q.image_url IS e.image_url AND q.syllabus_topic_id IS e.syllabus_topic_id AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective AND q.source_paper_code IS e.source_paper_code AND q.source_question_number IS e.source_question_number AND q.exam_board_id IS e.exam_board_id) = 6 AND (SELECT COUNT(*) FROM question_content_releases r JOIN _migration_626_expected e ON e.id = r.question_id WHERE r.batch_id IS 'bece-int-science-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned BECE Integrated Science practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/common-core-programme-ccp/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1) = 6 AND (SELECT COUNT(*) FROM questions q JOIN topics t ON t.id = q.topic_id AND t.subject_id = q.subject_id JOIN _migration_626_expected e ON e.id = q.id) = 6 AND (SELECT COUNT(*) FROM structured_question_parts sp JOIN _migration_626_expected_parts p ON p.id = sp.id AND sp.id IS p.id AND sp.question_id IS p.question_id AND sp.part_label IS p.part_label AND sp.part_text IS p.part_text AND sp.marks IS p.marks AND sp.correct_answer IS p.correct_answer AND sp.display_order IS p.display_order) = 6 THEN 1 ELSE 0 END;
